// 示例代码：动作与 EntryRow 组件
use gpui::{actions, ClickEvent, ScrollStrategy, SharedString};
use gpui::{ClickEvent as _ClickEvent, IntoElement, RenderOnce};

actions!(
    mini_browser,
    [NextEntry, PrevEntry, ToggleExpand, FocusSearch]
);

#[derive(IntoElement)]
struct EntryRow {
    ix: usize,
    row: Row,                       // Row 很小，直接按值传入
    selected: bool,
}

impl RenderOnce for EntryRow {
    fn render(self, _window: &mut Window, _cx: &mut App) -> impl IntoElement {
        div()
            .id(ElementId::Name(self.row.name))     // 有 id 才有 hover/active 状态样式
            .w_full()
            .pl(px(self.row.depth as f32 * 16.))    // 扁平缩进：宽度 = 深度 × 16px
            .when(self.selected, |el| el.bg(gpui::blue().opacity(0.2)))
            .child(if self.row.is_dir { "▸ " } else { "  " })
            .child(self.row.name.clone())
    }
}
```

（`ElementId::Name` 接受 `SharedString`；同一层兄弟 id 必须唯一，见 u5-l2 的状态串扰警告。）

